steps.command:
sqlite3 oewn.sqlite "
SELECT 'dup_synsetids', COUNT(*) FROM (SELECT synsetid FROM synsets GROUP BY synsetid HAVING COUNT(*)>1);
SELECT 'dup_words', COUNT(*) FROM (SELECT wordid FROM words GROUP BY wordid HAVING COUNT(*)>1);
SELECT 'distinct_wordid_senses', COUNT(DISTINCT wordid) FROM senses;
SELECT 'senses_not_in_synsets', COUNT(*) FROM senses s LEFT JOIN synsets y ON s.synsetid=y.synsetid WHERE y.synsetid IS NULL;
"

sqlite3 oewn.sqlite "
SELECT COUNT(*) FROM (SELECT wordid FROM senses GROUP BY wordid HAVING COUNT(*)>=2);
SELECT COUNT(*) FROM (SELECT wordid FROM senses GROUP BY wordid HAVING COUNT(*)>=2 AND COUNT(DISTINCT synsetid)>=2);
SELECT COUNT(DISTINCT domainid) FROM synsets;
SELECT COUNT(DISTINCT domainid) FROM domains;
"
